using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.Build;using UnityEditor.Build.Reporting;using UnityEngine;using UnityEngine.Rendering;
[InitializeOnLoad]public static class VoyageAndroidSetup {
 const string Command="Temp/mobile-command.txt",Folder="Tools/MobileUpdate";
 static VoyageAndroidSetup(){EditorApplication.update+=Poll;}
 static void Status(string message){Directory.CreateDirectory(Folder);File.WriteAllText(Folder+"/status.txt",message);}
 static void Poll(){if(!File.Exists(Command)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;var cmd=File.ReadAllText(Command).Trim();File.Delete(Command);try{if(cmd=="configure")Configure();else if(cmd=="test")VoyageMobileCheck.Begin();else if(cmd=="phone")VoyageGameView.Set(1600,720);else if(cmd=="tablet")VoyageGameView.Set(1024,768);else if(cmd=="android"){Configure();Status("Switching to Android");EditorUserBuildSettings.SwitchActiveBuildTargetAsync(BuildTargetGroup.Android,BuildTarget.Android);}else if(cmd=="build")Build();if(cmd!="build"&&cmd!="android")Status(cmd+" OK");}catch(Exception e){Status(e.ToString());Debug.LogException(e);}}
 public static void Configure(){if(EditorApplication.isPlaying)throw new Exception("Stop Play Mode before configuration");PlayerSettings.productName="Remnants of the Sea";PlayerSettings.defaultInterfaceOrientation=UIOrientation.AutoRotation;PlayerSettings.allowedAutorotateToLandscapeLeft=true;PlayerSettings.allowedAutorotateToLandscapeRight=true;PlayerSettings.allowedAutorotateToPortrait=false;PlayerSettings.allowedAutorotateToPortraitUpsideDown=false;PlayerSettings.defaultScreenWidth=1600;PlayerSettings.defaultScreenHeight=720;PlayerSettings.SetApplicationIdentifier(NamedBuildTarget.Android,"com.andronovagames.remnantsofthesea");PlayerSettings.SetScriptingBackend(NamedBuildTarget.Android,ScriptingImplementation.IL2CPP);PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;PlayerSettings.Android.minSdkVersion=AndroidSdkVersions.AndroidApiLevel25;PlayerSettings.Android.targetSdkVersion=AndroidSdkVersions.AndroidApiLevel35;PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.Android,false);PlayerSettings.SetGraphicsAPIs(BuildTarget.Android,new[]{GraphicsDeviceType.OpenGLES3});EditorUserBuildSettings.buildAppBundle=false;AssetDatabase.SaveAssets();}
 static void Build(){if(EditorApplication.isPlaying)throw new Exception("Stop Play Mode before building");if(EditorUserBuildSettings.activeBuildTarget!=BuildTarget.Android)throw new Exception("Switch to Android before building");Configure();Directory.CreateDirectory("Builds/Android");Status("Building Android ARM64 APK");var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/MainMenu.unity",StorySceneJourney.UnderwaterPath,StorySceneJourney.ShipPath},target=BuildTarget.Android,locationPathName="Builds/Android/RemnantsOfTheSea.apk",options=BuildOptions.Development});Status(report.summary.result+"\n"+report.summary.outputPath+"\nBytes: "+report.summary.totalSize+"\nErrors: "+report.summary.totalErrors+"\nTime: "+report.summary.totalTime);}
}

